-- D01 2015 Mazda Mazda3 (CERTIFIED, SOLD)
SET @v = (SELECT id FROM vehicle WHERE dealer_id = @d01 AND vin = '3MZBM1L75FM193583');
INSERT INTO work_order (dealer_id, vehicle_id, task, assignee_username, status, due_on, cost, completion_note, completed_on, version, created_at, updated_at)
SELECT @d01, @v, 'Replace front struts and mounts', 'emma.patel', 'DONE', '2026-01-14', 1040.00, 'Front struts leaking and mounts knocking over bumps. Installed complete strut assemblies, aligned afterwards.', '2026-01-09', 2, '2026-01-06 19:29:07', '2026-01-09 13:30:14'
FROM DUAL WHERE @v IS NOT NULL AND NOT EXISTS (SELECT 1 FROM work_order WHERE vehicle_id = @v AND task = 'Replace front struts and mounts');
INSERT INTO work_order (dealer_id, vehicle_id, task, assignee_username, status, due_on, cost, completion_note, completed_on, version, created_at, updated_at)
